 "content": "def transform(grid):
    """Duplicate the shape motifs in each color region along its mirror axes."""
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]

    # Full-length 8 lines divide the canvas into panels. Each shape is mirrored
    # across these separators, completing its corresponding counterpart.
    row_bars = [r for r, row in enumerate(grid) if all(v == 8 for v in row)]
    col_bars = [c for c in range(w) if all(grid[r][c] == 8 for r in range(h))]

    for b in row_bars:
        for d in range(1, min(b + 1, h - b)):
            for c in range(w):
                above, below = grid[b - d][c], grid[b + d][c]
                if above not in (0, 8) and below == 0:
                    out[b + d][c] = above
                if below not in (0, 8) and above == 0:
                    out[b - d][c] = below

    for b in col_bars:
        for d in range(1, min(b + 1, w - b)):
            for r in range(h):
                left, right = grid[r][b - d], grid[r][b + d]
                if left not in (0, 8) and right == 0:
                    out[r][b + d] = left
                if right not in (0, 8) and left == 0:
                    out[r][b - d] = right
    return out
